import { Group, Vector3 } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} PrimitiveConfig
 * @property {string} name
 * @property {any} params
 */

/**
 * @typedef {Object} NodeConfig
 * @property {string} meshUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {PrimitiveConfig[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader               // returns a cached GLTF object
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]               // optional event dispatcher
 */

/**
 * Creates a stat‑tile node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// root container
	const root = new Group();

	// -------------------------------------------------
	// Load mesh (synchronous – cached)
	const gltf = ctx.glbLoader(config.meshUrl);
	const mesh = gltf.scene.clone();
	root.add(mesh);

	// -------------------------------------------------
	// Apply transforms
	if (config.position) {
		if (Array.isArray(config.position))
			root.position.set(...config.position);
		else
			root.position.set(
				config.position.x ?? 0,
				config.position.y ?? 0,
				config.position.z ?? 0
			);
	}
	if (config.rotation) {
		if (Array.isArray(config.rotation))
			root.rotation.set(...config.rotation);
		else
			root.rotation.set(
				config.rotation.x ?? 0,
				config.rotation.y ?? 0,
				config.rotation.z ?? 0
			);
	}
	if (config.scale) {
		if (Array.isArray(config.scale))
			root.scale.set(...config.scale);
		else
			root.scale.set(
				config.scale.x ?? 1,
				config.scale.y ?? 1,
				config.scale.z ?? 1
			);
	}

	// -------------------------------------------------
	// Apply cinematic primitives
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const p of config.cinematicPrimitives) {
			const fn = ctx.primitives[p.name];
			if (typeof fn === 'function') fn(root, p.params);
		}
	}

	// -------------------------------------------------
	// Interaction: hover lift (rise‑in) and click press‑down
	const originalY = root.position.y;
	const hoverTL = gsap.timeline({ paused: true });
	hoverTL.to(
		root.position,
		{
			y: originalY + 0.15,
			duration: 0.7,
			ease: 'power3.out',
		}
	);

	const pressTL = gsap.timeline({ paused: true });
	pressTL.to(
		root.scale,
		{
			x: 0.97,
			y: 0.97,
			z: 0.97,
			duration: 0.12,
			ease: 'back.out(1.7)',
		}
	);

	// -------------------------------------------------
	// Event handlers container
	root.userData.handlers = {
		hoverEnter: () => hoverTL.play(0),
		hoverLeave: () => hoverTL.reverse(),
		click: () => {
			pressTL.restart();
			if (typeof ctx.emit === 'function') {
				ctx.emit('hub-home.select');
			}
		},
	};

	// -------------------------------------------------
	// Cleanup routine
	root.userData.cleanup = () => {
		hoverTL.kill();
		pressTL.kill();

		// Dispose geometry & material of the cloned GLTF
		mesh.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				const mat = obj.material;
				if (Array.isArray(mat)) {
					mat.forEach((m) => m && m.dispose && m.dispose());
				} else if (mat && mat.dispose) {
					mat.dispose();
				}
			}
		});
	};

	return root;
}
